using ABetterU.Coach;
using UnityEditor;
using UnityEngine;

/// Direct access to runtime-generated views for visual inspection, without VR controllers.
public sealed class WellnessUiScreens : EditorWindow
{
    [MenuItem("A Better U/Preview screens")]
    static void Open() => GetWindow<WellnessUiScreens>("A Better U Screens");

    void OnGUI()
    {
        EditorGUILayout.LabelField("UI screen preview", EditorStyles.boldLabel);
        EditorGUILayout.HelpBox(
            "Enter Play Mode, then select a screen below. These are views generated by AppFlow, not separate scene files. " +
            "The selector does not sign in or load account data. Unsigned views show their loading placeholders.",
            MessageType.Info);

        var flow = Application.isPlaying ? Object.FindAnyObjectByType<AppFlow>() : null;
        using (new EditorGUI.DisabledScope(flow == null))
        {
            ScreenButton("Login", AppFlow.Stage.Login, flow);
            ScreenButton("Main dashboard", AppFlow.Stage.Home, flow);
            ScreenButton("My World", AppFlow.Stage.MyWorld, flow);
            ScreenButton("Food Diary", AppFlow.Stage.Diary, flow);
            ScreenButton("My Experiences", AppFlow.Stage.Experiences, flow);
        }
        if (flow == null)
            EditorGUILayout.HelpBox("Waiting for Play Mode and the app to finish starting.", MessageType.Warning);
        else
            EditorGUILayout.LabelField("Current view", flow.Current.ToString());

        EditorGUILayout.Space();
        EditorGUILayout.HelpBox("Capture the Game view using A Better U > Capture UI screenshot (Play Mode). Stop Play Mode when finished previewing.", MessageType.None);
    }

    static void ScreenButton(string title, AppFlow.Stage stage, AppFlow flow)
    {
        if (!GUILayout.Button(title, GUILayout.Height(32))) return;
        flow.PreviewScreenInEditor(stage);
        EditorApplication.ExecuteMenuItem("Window/General/Game");
    }

    void OnInspectorUpdate() => Repaint();
}
